import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o,a as r}from"./chunks/qr_libre2direct-calib-30.qmCsLi9X.js";import{_ as i,o as a,c as s,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{},"headers":[],"relativePath":"install/libre2.md","filePath":"install/libre2.md"}'),l={name:"install/libre2.md"};function h(d,t,u,p,c,b){return a(),s("div",null,[...t[0]||(t[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Libre Bluetooth</p></div><h3 id="libre-2-direct" tabindex="-1">Libre 2 Direct <a class="header-anchor" href="#libre-2-direct" aria-label="Permalink to &quot;Libre 2 Direct&quot;">​</a></h3><p>This describes how to enable direct Bluetooth connection between the sensor &amp; xDrip, without the need for a bridge.</p><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><p>The phone on which you installed xDrip has an NFC reader.</p><p>If the vendor app is installed on the same phone you&#39;re using for xDrip, <strong>you uninstalled it</strong>.<br> If it is installed on another phone or you&#39;re using the Bluetooth reader, you&#39;ve put these devices far away, or shielded them so that they won&#39;t interfere.</p><h4 id="setting-up-for-the-first-time" tabindex="-1">Setting Up for the first time <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Setting Up for the first time&quot;">​</a></h4><p>(Click <a href="#starting-libre-2-sensors">Start Sensor</a> for subsequent sensors).</p><div class="info custom-block"><p class="custom-block-title">Only Libre 2/2+ Europe sensor models are supported</p><p>You need to install the <a href="./../use/OOP.html#oop2">latest OOP2 app</a>.</p></div><p>Libre 2 reference documentation is <a href="https://www.minimallooper.com/post/how-to-setup-freestyle-libre-2-and-oop2-to-use-a-native-bluetooth-connection-in-xdrip" target="_blank" rel="noreferrer">here</a> but is not up to date anymore.</p><br><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><strong>Uninstall any app connected to the sensor and shield the reader before attempting to connect to xDrip.</strong><br> If you connect your sensor directly to xDrip you will permanently lose alarms on the vendor app or reader without possibility to recover.<br> If you&#39;re not sure this will work, use a sensor at end of life to test the system.<br> Like Libre bridges, success and reliability will vary depending on your phone.<br> Linking your sensor to xDrip will void the vendor warranty on the sensor Bluetooth feature.</p></div><h4 id="setup-xdrip" tabindex="-1">Set up xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Set up xDrip {#setup-xdrip}&quot;">​</a></h4><p>As a shortcut, you can scan the QR code shown below to load the settings needed for Libre 2/2+ direct using xDrip <a href="./../use/copysettings.html#auto-configure">Auto Configure</a> feature. If you are browsing the documentation from the phone on which you&#39;re installing xDrip, save the pictures first, and then load them in the auto configure &quot;image file&quot; feature.</p><p>They set <strong><a href="./../use/misc.html#oop2">calibration to off</a> - recommended for first use</strong>. If instead you want calibration, <a href="./libre2direct-calib.html">follow this</a>. The full list of imported settings is shown <a href="./libre2direct-qr-settings.html">here</a>.</p><p>QR Codes - Click image to expand</p><table tabindex="0"><thead><tr><th style="text-align:center;">No Calibration</th><th style="text-align:center;">With Calibration</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./libre2direct-qr-settings.html"><img src="'+o+'" style="zoom:50%;"></a></td><td style="text-align:center;"><a href="./libre2direct-calib.html"><img src="'+r+'" style="zoom:50%;"></a></td></tr></tbody></table><p>If you used the QR codes, you can skip to <a href="#starting-libre-2-sensors">Starting Libre 2 Sensors</a></p><h4 id="configure-nfc" tabindex="-1">Configure NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configure NFC&quot;">​</a></h4><p>Configure NFC exactly <a href="./../use/NFC.html">like this</a>.</p><h4 id="starting-libre-2-sensors" tabindex="-1">Starting Libre 2 Sensors <a class="header-anchor" href="#starting-libre-2-sensors" aria-label="Permalink to &quot;Starting Libre 2 Sensors&quot;">​</a></h4><p>Physically insert your Libre 2/2+ sensor and start it using either the reader device, or LibreLink. Make a note of the time that the sensor will be ready. If using the same phone as xDrip, disable LibreLink on the phone. You should see BG values when scanning it. Now wait 60 minutes until the sensor has warmed up and self-calibrated.</p><h4 id="connect-to-the-sensor" tabindex="-1">Connect to the sensor <a class="header-anchor" href="#connect-to-the-sensor" aria-label="Permalink to &quot;Connect to the sensor&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Stop Sensor</p></div><p>If you have a previous sensor connected to xDrip, stop the old sensor.</p><p>Scan the sensor with xDrip NFC and make sure you see the toast messages &quot;Scanning..&quot; and then &quot;Scanned OK!&quot;.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Hold the phone steady when scanning the sensor and don&#39;t move it: it&#39;s taking longer than reading the sensor as you usually do with the vendor app.<br> Remember you should wait one minute between two successive NFC scans.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Start Sensor</p></div><p>Start the sensor in xDrip. When required to enter the time you physically started the sensor, do not put a time earlier than reality to avoid having inconsistent values.</p><p>Wait 60 seconds and scan again with xDrip. This adds the sensor as the BT device that xDrip will take the readings from. Expect to see NEW SENSOR STARTED notification. If you are set to &quot;No calibration&quot;, you should see the first reading immediately. If you have set Calibration, you should then be in the &quot;Collecting Initial Readings&quot; screen. You will now need to wait between 3 and 15 minutes for 3 readings to be received, and then you will be taken to the <strong>Calibrate Sensor?</strong> prompt, unless you selected &quot;No calibration&quot; in <a href="./../use/misc.html#oop2">OOP2 settings</a>. After entering the calibration data, the Libre 2/2+ sensor should be bonded to xDrip, and should deliver readings every 5 minutes.</p><p>You can confirm that all is working by comparing to &quot;What it should look like&quot; <a href="./../troubleshoot/libre2direct.html#what-it-should-look-like">here</a></p><p>If you have trouble getting data directly from the sensor, scan it every 5 minutes with xDrip NFC until you reach the calibration request (applies if you selected the <a href="./../use/misc.html#oop2">calibration option</a> with OOP2).</p><br><h4 id="problems" tabindex="-1"><strong>Problems?</strong> <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;**Problems?**&quot;">​</a></h4><p>Try the <a href="./../troubleshoot/libre2direct.html">troubleshooting</a> page.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 7/12/2024</em></a></p>',37)])])}const w=i(l,[["render",h]]);export{y as __pageData,w as default};
